export type QuizQuestion = {
  id: number;
  question: string;
  statements?: Record<string, string>;
  options: string[];
  correct: number;
  explanation: string;
};

export type QuizData = {
  title: string;
  duration: number;
  negativeMarking: number;
  cutoff: number;
  questions: QuizQuestion[];
};

type PairSeed = {
  topic: string;
  category: string;
  one: string;
  two: string;
  correct: 0 | 1 | 2 | 3;
  why: string;
};

export type QuizSet = {
  slug: string;
  title: string;
  description: string;
  categories: string[];
  quiz: QuizData;
};

const PAIR_OPTIONS = [
  "1 only",
  "2 only",
  "Both 1 and 2",
  "Neither 1 nor 2",
];

function buildQuiz(title: string, seeds: PairSeed[], duration = 600): QuizData {
  return {
    title,
    duration,
    negativeMarking: 0.333,
    cutoff: Math.ceil(seeds.length * 0.6),
    questions: seeds.map((seed, index) => ({
      id: index + 1,
      question: `With reference to ${seed.topic}, consider the following statements:`,
      statements: { "1": seed.one, "2": seed.two },
      options: PAIR_OPTIONS,
      correct: seed.correct,
      explanation: seed.why,
    })),
  };
}

function makeSets(monthLabel: string, seeds: PairSeed[]): QuizSet[] {
  return Array.from({ length: 5 }, (_, index) => {
    const questions = seeds.slice(index * 5, index * 5 + 5);
    return {
      slug: `set-${index + 1}-english`,
      title: `${monthLabel} 2026 - Quiz ${index + 1}`,
      description: "Five UPSC-level statement questions with current-static linkages.",
      categories: [...new Set(questions.map((question) => question.category))],
      quiz: buildQuiz(`${monthLabel} 2026 - Quiz ${index + 1}`, questions, 600),
    };
  });
}

