export const CURRENT_AFFAIRS_2026: Record<string, QuizSet[]> = {
  "2026-01": makeSets("January", JANUARY),
  "2026-02": makeSets("February", FEBRUARY),
  "2026-03": makeSets("March", MARCH),
  "2026-04": makeSets("April", APRIL),
  "2026-05": makeSets("May", MAY),
  "2026-06": makeSets("June", JUNE),
};

export function getCurrentAffairsQuiz(month: string, slug: string) {
  return CURRENT_AFFAIRS_2026[month]?.find((set) => set.slug === slug)?.quiz ?? null;
}

