export const STATIC_QUIZZES: QuizSet[] = Object.entries(STATIC_SEEDS).map(([slug, subject]) => ({
  slug,
  title: subject.label,
  description: subject.description,
  categories: [subject.category],
  quiz: buildQuiz(`${subject.label} - UPSC Foundation Test`, subject.seeds, 720),
}));

export function getStaticQuiz(slug: string) {
  return STATIC_QUIZZES.find((set) => set.slug === slug)?.quiz ?? null;
}

